// 0x7001 event record. The command buffer's stream was accepted and all its work submitted to the host GPU queue.
// kernel_start_time is when the host began processing the command buffer and kernel_end_time when it had submitted
// all its work, the two times the kernel's scheduled notification carries (IOGPUFamily's IOGPUCommandQueue reads the
// clock when it begins a submission and again once the command buffer is processed and submitted, and IOGPU passes
// both to didScheduleWithStartTime:endTime:error:, which stores kernelStartTime and kernelEndTime).
struct CommandBufferScheduled {
    static constexpr uint16_t kOpcode = 0x7001;
    uint64_t commandBuffer = 0;  // wire type `CommandBuffer`.
    uint64_t kernelStartTime = 0;  // wire type `u64`.
    uint64_t kernelEndTime = 0;  // wire type `u64`.
};

inline bool decodeFields(Reader& r, CommandBufferScheduled& v) {
    if (!r.u64(v.commandBuffer)) return false;
    if (v.commandBuffer == 0) return r.fail(DecodeError::NullHandle);
    if (!r.u64(v.kernelStartTime)) return false;
    if (!r.u64(v.kernelEndTime)) return false;
    return true;
}

// 0x7002 event record. The command buffer finished: status is MTLCommandBufferStatusCompleted or
// MTLCommandBufferStatusError. failure.status is 0 on success; failed_offset is the stream byte offset of the record
// that failed, 0xffffffffffffffff when no single record did. All writes the command buffer made to CPU-visible
// memory are in guest memory before this event is posted.
struct CommandBufferCompleted {
    static constexpr uint16_t kOpcode = 0x7002;
    uint64_t commandBuffer = 0;  // wire type `CommandBuffer`.
    uint64_t status = 0;  // `MTLCommandBufferStatus`, wire type `u64`.
    Failure failure{};  // wire type `Failure`.
    uint64_t failedOffset = 0;  // wire type `u64`.
    uint64_t kernelStartTime = 0;  // wire type `u64`.
    uint64_t kernelEndTime = 0;  // wire type `u64`.
    uint64_t gpuStartTime = 0;  // wire type `u64`.
    uint64_t gpuEndTime = 0;  // wire type `u64`.
};

inline bool decodeFields(Reader& r, CommandBufferCompleted& v) {
    if (!r.u64(v.commandBuffer)) return false;
    if (v.commandBuffer == 0) return r.fail(DecodeError::NullHandle);
    if (!r.u64(v.status)) return false;
    if (!decodeFields(r, v.failure)) return false;
    if (!r.u64(v.failedOffset)) return false;
    if (!r.u64(v.kernelStartTime)) return false;
    if (!r.u64(v.kernelEndTime)) return false;
    if (!r.u64(v.gpuStartTime)) return false;
    if (!r.u64(v.gpuEndTime)) return false;
    return true;
}

// 0x7003 event record. A NotifyListener registration was reached; value is the event's signaled value at that time.
struct SharedEventListener {
    static constexpr uint16_t kOpcode = 0x7003;
    uint64_t event = 0;  // wire type `Event`.
    uint64_t token = 0;  // wire type `u64`.
    uint64_t value = 0;  // wire type `u64`.
};

inline bool decodeFields(Reader& r, SharedEventListener& v) {
    if (!r.u64(v.event)) return false;
    if (v.event == 0) return r.fail(DecodeError::NullHandle);
    if (!r.u64(v.token)) return false;
    if (!r.u64(v.value)) return false;
    return true;
}

// 0x7004 event record. The host GPU device was lost. Every in-flight and later command buffer completes with an
// error.
struct DeviceLost {
    static constexpr uint16_t kOpcode = 0x7004;
    Failure failure{};  // wire type `Failure`.
};

inline bool decodeFields(Reader& r, DeviceLost& v) {
    if (!decodeFields(r, v.failure)) return false;
    return true;
}

// One decoded event record.
using Event = std::variant<CommandBufferScheduled, CommandBufferCompleted, SharedEventListener, DeviceLost>;

// Decode the event record at the start of data; stores its length in *consumed.
inline bool decodeEvent(const uint8_t* data, size_t size, Event& out, size_t* consumed, DecodeError* error = nullptr) {
    uint16_t opcode = 0;
    size_t length = 0;
    DecodeError local;
    DecodeError* e = error ? error : &local;
    if (!splitRecord(data, size, opcode, length, e)) return false;
    Reader r(data, length, e);
    switch (opcode) {
    case CommandBufferScheduled::kOpcode: {
        CommandBufferScheduled v;
        if (!decodeFields(r, v) || !r.finish()) return false;
        out = std::move(v);
        break;
    }
    case CommandBufferCompleted::kOpcode: {
        CommandBufferCompleted v;
        if (!decodeFields(r, v) || !r.finish()) return false;
        out = std::move(v);
        break;
    }
    case SharedEventListener::kOpcode: {
        SharedEventListener v;
        if (!decodeFields(r, v) || !r.finish()) return false;
        out = std::move(v);
        break;
    }
    case DeviceLost::kOpcode: {
        DeviceLost v;
        if (!decodeFields(r, v) || !r.finish()) return false;
        out = std::move(v);
        break;
    }
    default:
        e->kind = DecodeError::UnknownOpcode;
        e->offset = 0;
        return false;
    }
    *consumed = length;
    return true;
}

